.loginPassword&quot;,'/change-password',&quot;profile.set&quot;,'shield']]]]" :key="group" class="profile-group"><small>{{ $t(group) }}</small><RouterLink v-for="item in items" :key="item[0]" :to="path(item[1])"><Icon :name="item[3]"/><span>{{ $t(item[0]) }}</span><small>{{ $t(item[2]) }}</small><Icon name="chevron-right"/></RouterLink></div><div class="profile-group"><small>{{ $t("profile.groupPreferences") }}</small><label>{{ $t("common.language") }}<select :value="locale" @change="setLanguage($event.target.value)"><option v-for="[code,name] in languages" :value="code">{{ $t(name) }}</option></select></label></div></section><div><section class="profile-box"><header><h2>{{ $t("profile.myBusiness") }}</h2><small>{{ $t("profile.myBusinessHint") }}</small></header><div class="profile-group"><button @click="openModal('vip',&quot;profile.vipLevel&quot;)"><Icon name="trophy"/><span>{{ $t("profile.vipLevel") }}</span><small>{{ $t("VIP 0") }}</small><Icon name="chevron-right"/></button><RouterLink v-for="[name,to,icon] in [[&quot;promotion.cta.invite&quot;,'/referrals','users']]" :key="to" :to="path(to)"><Icon :name="icon"/><span>{{ $t(name) }}</span><Icon name="chevron-right"/></RouterLink></div></section><section class="profile-box"><header><h2>{{ $t("profile.support") }}</h2></header><div class="profile-group"><RouterLink :to="path('/help-center')">{{ $t("common.helpCenter") }}<Icon name="chevron-right"/></RouterLink><button @click="openModal('support',&quot;common.onlineSupport&quot;)">{{ $t("aiQuant.quantFund.topUp.contactSupport") }}<Icon name="chevron-right"/></button><RouterLink :to="path('/about')">{{ $t("common.aboutUs") }}<Icon name="chevron-right"/></RouterLink></div></section><button class="secondary-button wide-button" @click="openModal('account-confirm',&quot;profile.logoutConfirmTitle&quot;,{description:&quot;profile.logoutConfirmDescription&quot;,onConfirm:()=>{logout();router.push(path('/login'))}})">{{ $t("profile.logout") }}</button></div></div></template>
